css=''' :root{--paper:#f7f7f3;--ink:#151515;--red:#b32624}*{box-sizing:border-box}body{margin:0;background:#deded7;color:var(--ink);font-family:"Noto Sans CJK SC","Source Han Sans SC","PingFang SC","Microsoft YaHei",Arial,sans-serif;font-variant-numeric:tabular-nums}button,input{font:inherit}button{padding:9px 13px;border:1px solid #777;background:transparent;color:inherit;cursor:pointer}a{color:inherit}a:focus-visible,button:focus-visible,input:focus-visible{outline:3px solid var(--red);outline-offset:4px}nav{display:flex;flex-wrap:wrap;gap:10px;background:var(--paper);padding:14px 24px;border-bottom:1px solid #999}nav a{padding:9px;text-decoration:none}nav a[aria-current]{background:var(--ink);color:var(--paper)}.status{padding:10px 24px;font-size:13px}main{max-width:1440px;margin:auto}.page{background:var(--paper);padding:54px 72px 36px;min-height:900px;display:flex;flex-direction:column}.page[hidden]{display:none}body.overview .page[hidden]{display:flex}body.overview .page{margin-bottom:24px}h1,h2,h3,p{margin-top:0}h2{font-size:54px;line-height:1.17;margin-bottom:36px;letter-spacing:-.04em}h3{font-size:24px;line-height:1.5;margin-bottom:18px}p{font-size:22px;line-height:1.64;margin-bottom:27px}.meta,footer{font-size:18px;line-height:1.5}footer{display:flex;gap:24px;justify-content:space-between;padding-top:36px;margin-top:auto}.poster-layout{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:0 24px}.poster .meta{margin-bottom:54px}.title-first{grid-column:1/11;font-size:clamp(72px,9.2vw,132px);line-height:1.09;font-weight:700;letter-spacing:-.065em;margin:0}.title-second{grid-column:5/13;font-size:clamp(72px,9.2vw,132px);line-height:1.09;font-weight:700;letter-spacing:-.065em;margin:18px 0 54px}.poster-aside{grid-column:1/4;grid-row:3;font-size:22px}.poster-facts{grid-column:5/13;grid-row:3}.poster-facts p{margin:0;line-height:1.64}.poster-entry{grid-column:5/13;color:var(--red);font-size:36px;line-height:1.5;margin:45px 0 20px}.editorial{display:grid;grid-template-columns:3fr 4fr 4fr;gap:50px}.editorial h2{font-size:54px}.editorial .aside-note{font-size:24px;color:var(--red);margin-top:108px}.editorial article p{font-size:22px;line-height:1.64}.editorial section+section{margin-top:36px}.unknown-note{border-top:1px solid var(--ink);padding-top:18px;font-size:18px!important}.read-order{font-size:18px;margin-top:40px}.matrix-intro{font-size:22px}.matrix-layout{display:grid;grid-template-columns:minmax(0,9fr) minmax(170px,2fr);gap:70px;margin:20px 0 30px}.matrix{border-collapse:collapse;width:100%;text-align:left;font-size:20px}.matrix th{font-size:22px;font-weight:700;line-height:1.4;border-bottom:3px solid var(--ink);padding:12px 10px;vertical-align:bottom}.matrix td,.matrix tbody th{font-size:20px;font-weight:400;padding:8px 10px;border-bottom:1px solid #aaa;line-height:1.5}.matrix th:first-child{width:24%}.matrix .round{display:block}.matrix-notes p{font-size:18px;line-height:1.5}.red{color:var(--red)}.time-note p{margin-bottom:0}.directory-layout{display:grid;grid-template-columns:3fr 8fr;gap:130px}.directory-intro{padding-top:115px}.directory-intro p{font-size:22px}.directory-list{margin:36px 0 0;padding:0;list-style:none}.directory-list li+li{margin-top:65px}.directory-link{display:grid;grid-template-columns:145px minmax(0,1fr);gap:45px;text-decoration:none}.directory-link:hover .question{text-decoration:underline;text-underline-offset:6px}.page-number{font-size:96px;line-height:1.05;color:var(--red);font-weight:700}.question{font-size:30px;line-height:1.4;margin-bottom:12px;display:block}.directory-description{font-size:22px;line-height:1.6;display:block}.directory-caption{font-size:18px;line-height:1.5;display:block;margin-top:12px}.number-note{font-size:18px;color:var(--red)}details.editor{max-width:1440px;margin:20px auto;padding:20px 24px;background:white}summary{font-size:19px;cursor:pointer}.tools{display:flex;gap:12px;flex-wrap:wrap;margin:20px 0;align-items:center}.tools label{display:flex;gap:8px;align-items:center;flex-wrap:wrap;max-width:100%;min-width:0}.tools input[type=file]{width:240px;max-width:100%;min-width:0}.tool-note{font-size:15px;line-height:1.6}.editing [data-edit]{outline:1px dashed var(--red);outline-offset:4px}[data-edit]{overflow-wrap:anywhere}.editor-footer{max-width:1440px;margin:0 auto 25px;padding:12px 24px;font-size:13px}body.mono{--red:var(--ink)}@media(max-width:1000px){.page{padding:40px 36px}.editorial{gap:30px;grid-template-columns:2fr 4fr 4fr}.editorial h2{font-size:40px}.matrix-layout{gap:30px}.directory-layout{gap:60px}.directory-link{gap:24px;grid-template-columns:110px 1fr}.page-number{font-size:80px}.question{font-size:27px}}@media(max-width:700px){nav{gap:0;padding:8px}nav a{font-size:14px;padding:8px}.status{padding:10px 18px}.page{padding:32px 22px;min-height:820px}h2{font-size:38px;line-height:1.2}.meta,footer{font-size:15px}.poster-layout{display:block}.poster .meta{margin-bottom:40px}.title-first,.title-second{font-size:clamp(54px,14vw,88px);line-height:1.15;margin:0;letter-spacing:-.055em}.title-second{margin:12px 0 40px}.poster-aside{font-size:20px;max-width:260px}.poster-facts p{font-size:20px}.poster-entry{font-size:28px;margin:40px 0 20px}.editorial{display:block}.editorial h2{font-size:40px}.editorial .aside-note{margin:24px 0 40px;font-size:22px}.editorial article p{font-size:22px}.editorial article+article{margin-top:36px}.matrix-layout{display:block}.matrix thead{display:none}.matrix,.matrix tbody,.matrix tr{display:block}.matrix tr{padding:16px 0;border-bottom:1px solid #aaa}.matrix tbody th:first-child{width:100%}.matrix tbody th{display:block;padding:0 0 8px;border:0;font-weight:700;width:100%}.matrix td{display:flex;justify-content:space-between;gap:16px;padding:3px 0;border:0;font-size:20px}.matrix td::before{content:attr(data-label);font-size:18px}.matrix-notes{margin-top:30px}.time-note p,.matrix-intro{font-size:20px}.directory-layout{display:block}.directory-intro{padding:0}.directory-list{margin-top:40px}.directory-list li+li{margin-top:42px}.directory-link{grid-template-columns:70px minmax(0,1fr);gap:20px}.page-number{font-size:52px}.question{font-size:24px}.directory-description{font-size:20px}.directory-caption{font-size:16px}}@media print{body{background:white}nav,.status,.editor,.editor-footer{display:none!important}.page,.page[hidden]{display:flex!important;break-after:page;min-height:0;padding:15mm 10mm}.matrix thead{display:table-header-group}.matrix tr{break-inside:avoid}.matrix-notes{break-inside:avoid}}'''
def edit(key,text,tag='span',cls=''):return f'<{tag} data-edit="{key}"'+(f' class="{cls}"' if cls else '')+f'>{text}</{tag}>'
def foot(n):return f'<footer><span data-edit="disclaimer">虚构计划／暂无实测结果</span><span>{n}</span></footer>'
A='岸线并不只是一条轮廓。远看时，它是陆地与水的分界；靠近时，它又分成潮痕、碎石与水面的反光。一次记录总要选择视点，也会留下没有被记录的部分。'
B='这份计划用编号区分观察点，用轮次标签保存尚待安排的记录顺序。编号不表示地理位置，轮次不代表已经完成。清楚的版面可以帮助查找信息，但不能替代现场记录。'
C='这里设定了12个观察点、3轮记录和30分钟。点位与轮次如何对应，30分钟适用于单点、单轮还是整次活动，都还没有确定。所有空缺必须继续被看见，不能用图形把未知伪装成结果。'
body='<nav aria-label="四页切换">'+''.join(f'<a href="#{id}" data-page="{id}">{i+1:02} {name}</a>' for i,(id,name) in enumerate([('poster','招贴'),('reading','阅读'),('matrix','矩阵'),('directory','目录')]))+'</nav><div class="status">瑞士信息设计 · 独立候选｜原样例评价：差／二级｜未自动升等</div><main>'
body+='<section class="page poster" id="poster"><p class="meta">观察计划／平面研究</p><div class="poster-layout">'+edit('title-first','重新看见','h1','title-first')+edit('title-second','岸线','p','title-second')+edit('poster-aside','远看一条线，近看许多层次。','p','poster-aside')+'<div class="poster-facts"><p>12个观察点，位置待定。</p><p>3轮记录，分配待定。</p>'+edit('time-brief','时间设定30分钟，适用范围待定。','p')+'</div>'+edit('entry','先区分已知与未知。','p','poster-entry')+'</div>'+foot('01')+'</section>'
body+='<section class="page" id="reading"><div class="editorial"><aside><h2>观察<br>与记录</h2>'+edit('reading-note','排版组织信息，不能制造事实。','p','aside-note')+'</aside><article><section><h3>为什么观察</h3>'+edit('p1',A,'p')+'</section><section><h3>如何读这份计划</h3>'+edit('p2',B,'p')+'</section></article><article><h3>什么仍然未知</h3>'+edit('p3',C,'p')+edit('time-remark','30分钟的适用范围未定。','p','unknown-note')+'</article></div><p class="read-order">阅读顺序：为什么 → 如何读 → 未知事项</p>'+foot('02')+'</section>'
body+='<section class="page" id="matrix"><h2>点位 × 轮次</h2><p class="matrix-intro"><span class="red">分配关系尚未确定</span>；本表不表示每点必须参加每轮。</p><div class="matrix-layout"><table class="matrix"><thead><tr><th scope="col">观察点</th>'+''.join('<th scope="col">'+edit(f'round-{i}',f'R{i}／第{i}轮')+'</th>' for i in range(1,4))+'</tr></thead><tbody>'
for n in range(1,13):body+='<tr><th scope="row">'+edit(f'point-{n}',f'{n:02}')+'</th>'+''.join(f'<td data-round="{i}" data-label="R{i}／第{i}轮">待分配</td>' for i in range(1,4))+'</tr>'
body+='</tbody></table><aside class="matrix-notes"><p>R1–R3只是轮次标签，尚未实施。</p><p>36个交叉位置是关系模板，不是36份记录或任务承诺。</p></aside></div><div class="time-note"><p data-edit="time-matrix">时间设定：30分钟。</p>'+edit('time-scope','适用于单点、单轮或整次活动，仍待确定。','p')+'</div>'+foot('03')+'</section>'
body+='<section class="page" id="directory"><h2>从问题进入</h2><div class="directory-layout"><aside class="directory-intro">'+edit('directory-intro','主题、方法、计划各有位置。先找到要问的问题，再阅读对应页面。','p')+'<p class="number-note">数字为页码，非活动轮次。</p></aside><ol class="directory-list">'
for i,(target,q,d,c) in enumerate([('poster','这是什么？','看主题：重新看见岸线。','主题招贴 · 第01页'),('reading','如何理解这份计划？','读说明：观察、记录与未知。','连续阅读 · 第02页'),('matrix','哪里尚待安排？','查分配：点位与轮次。','计划矩阵 · 第03页')],1):body+=f'<li><a class="directory-link" href="#{target}" data-page="{target}"><span class="page-number">{i:02}</span><span>'+edit(f'question-{i}',q,'strong','question')+edit(f'description-{i}',d,'span','directory-description')+f'<span class="directory-caption">{c}</span></span></a></li>'
body+='</ol></div>'+foot('04')+'</section></main><details class="editor"><summary>编辑与导出</summary><div class="tools"><button id="edit" aria-pressed="false">编辑文字</button><button id="overview" aria-pressed="false">四页并看</button><button id="mono" aria-pressed="false">黑白检查</button><button id="reset">恢复初始版本</button></div><div class="tools"><label>主墨 <input type="color" id="ink" value="#151515"></label><label>强调红 <input type="color" id="red" value="#b32624"></label><button id="json-export">下载编辑数据 JSON</button><button id="html-export">下载可编辑 HTML</button><label>导入 JSON <input id="json-import" type="file" accept=".json,application/json"></label></div><p class="tool-note">编辑点位、轮次标签及文字。轮次标签会同步到手机矩阵字段；相同限定声明同步四页。状态保持待分配，修改文本不等于产生实测结果。各处时间与正文分别编辑，修改后须人工核对跨页事实一致；默认30分钟及其适用范围待定。退出编辑可使用目录链接。</p><p id="edit-status" role="status" class="tool-note">默认静态，无动画，暂停不适用。系统减少动效不影响内容与功能。</p><p class="tool-note">系统中文黑体未随包分发；自定颜色需重新查对比度。打印与跨平台字体另验。</p></details><div class="editor-footer">SW-INFO-01 · 原创中文排印适配。历史资料仅研究引用，未复制SBB标识、样图或字体。</div>'
model={'schemaVersion':1,'designVersion':'SW-INFO-01','qualityTag':'差','adaptationLevel':2,'candidate':True,'text':{},'colors':{'ink':'#151515','red':'#b32624'}}
